fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Check if the subarray matches the main array starting at the given index
    for j in 0..sub.len() {
        if main[start + j] != sub[j] {
            return false;
        }
    }
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // If the subarray is empty, return true
    if sub.is_empty() {
        return true;
    }
    
    // If the subarray is longer than the main array, return false
    if sub.len() > main.len() {
        return false;
    }
    
    // Check for matches starting from each index in the main array
    for i in 0..=main.len() - sub.len() {
        if check_match_at(main, sub, i) {
            return true;
        }
    }
    
    false
}

// Example usage
fn main() {
    let main_array = vec![1, 2, 3, 4, 5];
    let sub_array = vec![3, 4];
    let result = is_sub_array(&main_array, &sub_array);
    println!("Is subarray: {}", result); // Should print: Is subarray: true
}